package gosu.gsp.compilerbridge;

import java.io.File;
import java.lang.reflect.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

/** Runs only the SDK parser/type checker. No program evaluation or generated bytecode execution. */
public final class GosuCompilerBridge {
  private GosuCompilerBridge() {}
  public static void main(String[] args) {
    try {
      File source = new File(args[0]);
      List<Object> classpath = new ArrayList<>();
      Object filesystem = Class.forName("gw.config.CommonServices").getMethod("getFileSystem").invoke(null);
      Method directory = Class.forName("gw.lang.reflect.module.IFileSystem").getMethod("getIDirectory", File.class);
      for (int i = 2; i < args.length; i++) classpath.add(directory.invoke(filesystem, new File(args[i])));
      Class.forName("gw.lang.Gosu").getMethod("init", List.class).invoke(null, classpath);
      if (source.getName().endsWith(".gsp")) {
        Object parser = Class.forName("gw.lang.parser.GosuParserFactory").getMethod("createProgramParser").invoke(null);
        Object symbols = Class.forName("gw.lang.parser.StandardSymbolTable").getConstructor(boolean.class).newInstance(true);
        Object options = Class.forName("gw.lang.parser.ParserOptions").getConstructor().newInstance();
        Class.forName("gw.lang.parser.IGosuProgramParser").getMethod("parseExpressionOrProgram", String.class,
            Class.forName("gw.lang.parser.ISymbolTable"), options.getClass())
            .invoke(parser, Files.readString(source.toPath(), StandardCharsets.UTF_8), symbols, options);
      } else {
        Object type = Class.forName("gw.lang.reflect.TypeSystem").getMethod("getByFullName", String.class).invoke(null, args[1]);
        boolean valid = (boolean) Class.forName("gw.lang.reflect.IType").getMethod("isValid").invoke(type);
        if (!valid) {
          Object errors = Class.forName("gw.lang.reflect.gs.IGosuClass").getMethod("getParseResultsException").invoke(type);
          if (errors instanceof Throwable) throw (Throwable) errors;
          throw new IllegalStateException("Gosu rejected the type without diagnostics");
        }
      }
      System.out.println("GOSU_DONE");
    } catch (Throwable failure) {
      Throwable cause = unwrap(failure);
      try {
        if (cause.getClass().getName().equals("gw.lang.parser.exceptions.ParseResultsException")) {
          Collection<?> issues = (Collection<?>) cause.getClass().getMethod("getParseIssues").invoke(cause);
          for (Object issue : issues) {
            Class<?> api = Class.forName("gw.lang.parser.IParseIssue");
            int line = ((Number) api.getMethod("getLine").invoke(issue)).intValue();
            int column = ((Number) api.getMethod("getColumn").invoke(issue)).intValue();
            String message = String.valueOf(api.getMethod("getUIMessage").invoke(issue));
            String severity = issue.getClass().getSimpleName().contains("Warning") ? "WARNING" : "ERROR";
            System.out.println("GOSU_DIAG\t" + severity + "\t" + line + "\t" + column + "\t" + encode(message));
          }
          System.out.println("GOSU_DONE");
        } else {
          System.out.println("GOSU_FAILURE\t" + encode(cause.toString()));
        }
      } catch (Throwable unsupportedSdk) {
        System.out.println("GOSU_FAILURE\t" + encode(unwrap(unsupportedSdk).toString()));
      }
    }
  }
  private static String encode(String text) { return Base64.getEncoder().encodeToString(text.getBytes(StandardCharsets.UTF_8)); }
  private static Throwable unwrap(Throwable failure) {
    while (failure instanceof InvocationTargetException && failure.getCause() != null) failure = failure.getCause();
    return failure;
  }
}
